stmt.execute("""
    CREATE TABLE users (
        id INT PRIMARY KEY,
        name VARCHAR(100) NOT NULL,
        middle_name VARCHAR(100),
        age INT
    )
    """);
// "name" jest NOT NULL (wymagane), "middle_name" i "age" opcjonalne.

stmt.execute("INSERT INTO users (id, name, middle_name, age) VALUES (1, 'Jan Kowalski', 'Piotr', 30)");
stmt.execute("INSERT INTO users (id, name, middle_name, age) VALUES (2, 'Anna Nowak', NULL, NULL)");

ResultSet rs = stmt.executeQuery("SELECT name FROM users WHERE middle_name IS NULL");
// Do sprawdzania NULL uzywamy IS NULL / IS NOT NULL, NIGDY "= NULL"

try {
    stmt.execute("INSERT INTO users (id, name) VALUES (3, NULL)");
} catch (SQLException e) {
    System.out.println("Odrzucono przez ograniczenie NOT NULL: " + e.getMessage());
}

// Ograniczenie NOT NULL na poziomie definicji kolumny CALKOWICIE
// ZABRANIA wstawienia NULL do tej kolumny - baza odrzuci probe bledem.

ResultSet rs = stmt.executeQuery("SELECT name, age FROM users ORDER BY id");
while (rs.next()) {
    String name = rs.getString("name");
    int ageAsInt = rs.getInt("age");
    boolean wasNull = rs.wasNull(); // MUSI byc wywolane zaraz po getInt()!
    System.out.println(name + ": getInt()=" + ageAsInt + ", wasNull()=" + wasNull);
}
// Anna Nowak: getInt()=0, wasNull()=true   <- 0 to FALSZYWY wiek!

// Bezpieczniejsza alternatywa:
Integer ageOrNull = (Integer) rs.getObject("age");
Optional<Integer> age = Optional.ofNullable(ageOrNull);
System.out.println(name + ": age=" + age.map(String::valueOf).orElse("brak danych"));
